            (m = (out = PointMass(1.0), in1 = NormalMeanPrecision(4.0, 7.0)),) => NormalMeanPrecision(3.0, 7.0),
            (m = (out = PointMass(-3.0), in1 = NormalMeanPrecision(-1.0, 2.0)),) => NormalMeanPrecision(2.0, 2.0),
