            (m = (out = MvNormalMeanPrecision([-4.0, 3.0], [3.0 2.0; 2.0 4.0]), in1 = PointMass([3.0, 2.0])),) => MvNormalMeanPrecision([7.0, -1.0], [3.0 2.0; 2.0 4.0]),
