            (m = (out = MvNormalMeanPrecision([1.0, 0.0], [2.0 0.0; 0.0 1.0]), in1 = MvNormalMeanPrecision([1.0, -7.0], [2.0 0.0; 0.0 3.0])),) => MvNormalMeanCovariance([0.0, -7.0], [1.0 0.0; 0.0 4 / 3]),
            (m = (out = MvNormalMeanCovariance([1.0, -1.0], [3.0 1.0; 1.0 4.0]), in1 = MvNormalMeanPrecision([1.0, 4.0], [2.0 1.0; 1.0 3.0])),) => MvNormalMeanCovariance([0.0, 5.0], [36 / 10 4 / 5; 4 / 5 44 / 10]),
            (m = (out = MvNormalMeanPrecision([1.0, 0.0], [2.0 0.0; 0.0 1.0]), in1 = MvNormalWeightedMeanPrecision([1.0, -7.0], [2.0 0.0; 0.0 3.0])),) => MvNormalMeanCovariance([-1 / 2, -7 / 3], [1.0 0.0; 0.0 4 / 3]),
