            (m = (out = MvNormalWeightedMeanPrecision([1.0, -7.0], [2.0 0.0; 0.0 3.0]), in1 = MvNormalMeanPrecision([1.0, 0.0], [2.0 0.0; 0.0 1.0])),) => MvNormalMeanCovariance([1 / 2, 7 / 3], [1.0 0.0; 0.0 4 / 3]),
            (m = (out = MvNormalWeightedMeanPrecision([1.0, 4.0], [2.0 1.0; 1.0 3.0]), in1 = MvNormalMeanCovariance([1.0, 1.0], [3.0 1.0; 1.0 4.0])),) => MvNormalMeanCovariance([6 / 5, -2 / 5], [36 / 10 4 / 5; 4 / 5 44 / 10]),
